// === Tab: mySketch ===
let particles = [];
let textInput, dissolveSlider, densitySlider, sizeSlider, modeSelect;
let pg; 
let showBackground = true;

function setup() {
  createCanvas(1000, 600);
  pixelDensity(1);

  // --- ИНТЕРФЕЙС ---
  let title = createElement('h2', 'Пирс 5 Particle Dissolve генератор');
  title.position(20, 0);
  title.style('font-family', 'sans-serif');

  // Ряд 1: Текст, Распад, Тип
  let r1y = 70; // Координата Y для первого ряда
  createLabel("ТЕКСТ:", 20, r1y);
  textInput = createInput('INTENSUM');
  textInput.position(20, r1y + 15);
  textInput.size(140);
  textInput.input(generateParticles);

  createLabel("РАСПАД:", 200, r1y);
  dissolveSlider = createSlider(0, 1, 0, 0.001);
  dissolveSlider.position(200, r1y + 15);
  dissolveSlider.size(150);

  createLabel("ТИП РАСПАДА:", 380, r1y);
  modeSelect = createSelect();
  modeSelect.position(380, r1y + 15);
  modeSelect.size(150);
  modeSelect.option('Слева направо', 'LtoR');
  modeSelect.option('Справа налево', 'RtoL');
  modeSelect.option('Из центра', 'Center');

  // Ряд 2: Плотность, Размер, Кнопки
  let r2y = 120; // Координата Y для второго ряда
  createLabel("ПЛОТНОСТЬ:", 20, r2y);
  densitySlider = createSlider(1, 6, 2, 1);
  densitySlider.position(20, r2y + 15);
  densitySlider.input(generateParticles);

  createLabel("РАЗМЕР ЧАСТИЦ:", 200, r2y);
  sizeSlider = createSlider(0.5, 8, 2, 0.5);
  sizeSlider.position(200, r2y + 15);

  // Кнопки
  let toggleBg = createButton('Фон: Вкл/Выкл');
  toggleBg.position(380, r2y + 10);
  toggleBg.size(150, 25);
  toggleBg.mousePressed(() => showBackground = !showBackground);

  let saveBtn = createButton('СОХРАНИТЬ PNG');
  saveBtn.position(550, r2y + 5);
  saveBtn.size(180, 35);
  saveBtn.style('background-color', '#000');
  saveBtn.style('color', '#fff');
  saveBtn.style('cursor', 'pointer');
  saveBtn.style('border', 'none');
  saveBtn.style('font-weight', 'bold');
  saveBtn.mousePressed(exportPNG);

  pg = createGraphics(width, height);
  pg.pixelDensity(1); 
  generateParticles();
}

function createLabel(txt, x, y) {
  let l = createP(txt);
  l.position(x, y);
  l.style('font-family', 'sans-serif');
  l.style('font-size', '10px');
  l.style('font-weight', 'bold');
  l.style('margin', '0'); // Убираем внешние отступы
  l.style('padding', '0'); // Убираем внутренние отступы
}

function generateParticles() {
  particles = [];
  let txt = textInput.value().toUpperCase();
  let step = densitySlider.value(); 

  pg.clear();
  pg.background(0); 
  pg.fill(255);     
  pg.textAlign(CENTER, CENTER);
  pg.textSize(150);
  pg.textFont('sans-serif'); 
  // Сместил текст чуть ниже, чтобы UI не мешал обзору
  pg.text(txt, width / 2, height / 2 + 100); 

  pg.loadPixels();

  for (let y = 0; y < pg.height; y += step) {
    for (let x = 0; x < pg.width; x += step) {
      let index = (x + y * pg.width) * 4;
      if (pg.pixels[index] > 128) {
        particles.push({
          origX: x,
          origY: y,
          noiseX: random(-80, 80),
          noiseY: random(-40, 40),
          angle: atan2(y - (height/2 + 100), x - (width/2)) 
        });
      }
    }
  }
}

function draw() {
  if (showBackground) background(245);
  else clear();

  stroke(0); 

  let dVal = dissolveSlider.value();
  let mode = modeSelect.value();
  let baseSize = sizeSlider.value();

  for (let p of particles) {
    let distancePast = 0;
    let driftX = 0;
    let driftY = 0;

    if (mode === 'LtoR') {
      let threshold = map(dVal, 0, 1, -100, width + 100);
      distancePast = threshold - p.origX;
      driftX = -distancePast * 0.3;
    } 
    else if (mode === 'RtoL') {
      var threshold = map(dVal, 0, 1, width + 100, -100);
      distancePast = p.origX - threshold;
      driftX = distancePast * 0.3;
    } 
    else if (mode === 'Center') {
      let maxDist = 400;
      var threshold = dVal * maxDist;
      let dToCenter = dist(p.origX, p.origY, width/2, height/2 + 100);
      distancePast = threshold - dToCenter;
      driftX = cos(p.angle) * distancePast * 0.5;
      driftY = sin(p.angle) * distancePast * 0.5;
    }

    if (distancePast > 0) {
      let spread = map(distancePast, 0, 400, 0, 1, true);
      let offsetX = (p.noiseX * pow(spread, 1.4));
      let offsetY = (p.noiseY * pow(spread, 1.4));

      strokeWeight(map(spread, 0, 1, baseSize, 0.1));
      point(p.origX + offsetX + driftX, p.origY + offsetY + driftY);
    } else {
      strokeWeight(baseSize);
      point(p.origX, p.origY);
    }
  }
}

function exportPNG() {
  let wasShowing = showBackground;
  showBackground = false;
  draw(); 
  saveCanvas('Pierce5_' + textInput.value(), 'png');
  showBackground = wasShowing;
}

